Usage: TSAutoBufferConfigconfig;
config.max_points_per_buffer=500;
config.flush_interval=std::chrono::seconds(10);

TSAutoBufferbuffer(tsstore,config);
buffer.start();//Startbackgroundflushthread

//Addpoints(willbebuffered)
buffer.add(point1);
buffer.add(point2);
//...pointsareautomaticallyflushedinbatches

buffer.stop();//Stopandflushremainingpoints
